(function(root){'use strict';
 let framing='full',view='front';let timer,resizeTimer,stopped=false,readySent=false,focused=false;function control(action,value){if(['focus','framing','view'].includes(action))focused=true;if(action==='focus')root.CozyWorld?.artLabFocusCharacter?.(view,framing);if(action==='framing'&&['full','head'].includes(value)){framing=value;root.CozyWorld?.artLabFocusCharacter?.(view,framing);}if(action==='lighting')root.CozyWorld?.artLabPreviewLighting?.(value);if(action==='version')root.CozyAvatarCandidate.setVersion(value);if(action==='view'&&['front','quarter','side','back'].includes(value)){view=value;root.CozyWorld?.artLabFocusCharacter?.(view,framing);}if(action==='motion'){if(value==='wave')root.CozyWorld?.wave();else if(value!=='idle')root.CozyWorld?.notify('點地面散步，或從原遊戲介面與人物、家具互動。');}}
 addEventListener('message',event=>{if(event.source===parent&&event.origin===location.origin&&event.data?.type==='avatar-artlab/control')control(event.data.action,event.data.value);});
 const refocus=()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(()=>{if(!stopped&&focused)root.CozyWorld?.artLabFocusCharacter?.(view,framing);},350);};const canvas=root.CozyWorld?.canvas,observer=typeof ResizeObserver==='function'&&canvas?.parentElement?new ResizeObserver(refocus):null;observer?.observe(canvas.parentElement);addEventListener('resize',refocus);canvas?.addEventListener('pointerdown',()=>{focused=false;},{passive:true});addEventListener('cozy-scene',()=>{focused=false;});
 const poll=()=>{if(stopped||document.hidden)return;const s=root.CozyWorld?.state?.();if(!s)return;if(!readySent&&s.active&&document.querySelector('#presence-status')?.textContent==='即時同步中'){readySent=true;parent.postMessage({type:'avatar-artlab/ready'},location.origin);}parent.postMessage({type:'avatar-artlab/metrics',version:root.CozyAvatarCandidate.version,calls:s.drawCalls,triangles:s.triangles,geometries:s.rendererMemory?.geometries,textures:s.rendererMemory?.textures,frameP50Ms:s.meanFrameMs,frameP95Ms:null,contextLost:s.contextLost,scene:s.scene,hairAsset:root.CozyHairGLB?.stats(),hairAssetV1:root.CozyHairGLBV1?.stats()},location.origin);};timer=setInterval(poll,1000);
 root.AvatarArtLabGame=Object.freeze({control,focus:()=>root.CozyWorld?.artLabFocusCharacter?.(),get model(){return root.CozyAvatarCandidate.instances[0];},get state(){return root.CozyWorld?.state?.();}});
 addEventListener('pagehide',()=>{stopped=true;clearInterval(timer);clearTimeout(resizeTimer);observer?.disconnect();removeEventListener('resize',refocus);for(const m of root.CozyAvatarCandidate.instances)m.dispose();},{once:true});
})(window);
